// По одній клітинці з верхньої та нижньої сторін перенесено на бокові: 17 + 11 + 17 + 11 = 56.
function rectanglePosition(index,amount,ring){let w=amount===56?17:9,h=amount===56?11:5,per=2*(w+h),d=((Math.floor(w/2)+(ring==='outer'?-index:index))%per+per)%per;let x,y;if(d<=w){x=d/w;y=0}else if(d<=w+h){x=1;y=(d-w)/h}else if(d<=2*w+h){x=1-(d-w-h)/w;y=1}else{x=0;y=1-(d-2*w-h)/h}return{x,y}}
function renderBoard(){document.querySelectorAll('.cell').forEach(e=>e.remove());for(const[ring,board]of Object.entries(BOARDS))board.forEach((type,i)=>{let xy=rectanglePosition(i,board.length,ring),inset=ring==='inner'?.225:.05,span=1-2*inset;let cell=document.createElement('button');cell.type='button';cell.className=`cell ${ring} ${type}`;cell.dataset.ring=ring;cell.dataset.position=i;cell.style.left=(inset+xy.x*span)*100+'%';cell.style.top=(inset+xy.y*span)*100+'%';cell.setAttribute('aria-label',`${ring==='inner'?'Мале':'Велике'} коло, ${i+1}, ${TYPES[type][0]}`);cell.innerHTML=`<span class="number">${i+1}</span><span class="symbol">${TYPES[type][1]}</span><span>${TYPES[type][0]}</span><span class="tokens"></span>`;let group=players.map((p,j)=>({...p,index:j})).filter(p=>p.ring===ring&&p.position===i);group.forEach((p,j)=>{let img=document.createElement('img');img.src=`images/${p.token}.png`;img.alt=p.name;img.title=p.name;img.draggable=false;img.className='token'+(p.index===currentIndex?' active-token':'');img.style.setProperty('--player',p.color);if(group.length>1){img.style.setProperty('--offset-x',((j%3)-(Math.min(group.length,3)-1)/2)*25+'px');img.style.setProperty('--offset-y',(Math.floor(j/3)-(Math.ceil(group.length/3)-1)/2)*33+'px')}img.onclick=e=>{e.stopPropagation();if(p.index!==currentIndex)notify('Зараз ходить '+players[currentIndex].name);else if(phase==='rolled')notify('Перетягни героя на підсвічену клітинку.');else showProfile(p.index)};img.onpointerdown=e=>beginDrag(e,p.index,img);cell.querySelector('.tokens').append(img)});if(phase==='rolled'&&target?.ring===ring&&target.position===i)cell.classList.add('target');cell.onclick=()=>placeToken(ring,i);$('board').append(cell)})}
function renderGame(){let p=players[currentIndex];$('currentHero').innerHTML=`<img src="images/${p.token}.png" alt=""><span>${esc(p.name)}</span>`;$('dice').textContent=roll?['⚀','⚁','⚂','⚃','⚄','⚅'][roll-1]+' '+roll:'⚄';let hints={awaitRoll:'Твій хід. Кинь кубик!',rolled:'Перетягни героя на підсвічену клітинку.',moved:'Герой на місці. Витягни картку!',read:'Картку прочитано. Можна завершити хід.',finished:'Гру завершено. Дякуємо за гру!'};$('turnHint').textContent=rolling?'Кубик обирає число…':hints[phase];$('newGame').disabled=rolling;$('endGame').disabled=rolling||phase==='finished';$('roll').disabled=rolling||phase!=='awaitRoll';$('draw').hidden=phase!=='moved';$('next').disabled=rolling||phase!=='read';$('roster').innerHTML=players.map((p,i)=>`<button class="player-row ${i===currentIndex?'active':''}" data-profile="${i}" style="--player:${p.color}" aria-label="Картка гравця ${esc(p.name)}"><img src="images/${p.token}.png" alt=""><span><strong>${esc(p.name)}</strong><small>${p.ring==='inner'?'Мале':'Велике'} коло · ${p.position+1}</small></span><span class="info-mark">ⓘ</span></button>`).join('');$('roster').querySelectorAll('button').forEach(b=>b.onclick=()=>showProfile(Number(b.dataset.profile)));renderBoard()}
async function rollDice(){if(rolling||phase!=='awaitRoll')return;rolling=true;renderGame();for(let i=0;i<8;i++){$('dice').textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][randomInt(6)];await new Promise(r=>setTimeout(r,65))}roll=randomInt(6)+1;let p=players[currentIndex];target={ring:p.ring,position:(p.position+roll)%BOARDS[p.ring].length};phase='rolled';rolling=false;renderGame()}
