function beginDrag(e,index,el){e.stopPropagation();if(index!==currentIndex){notify('Зараз ходить '+players[currentIndex].name);return}if(phase!=='rolled'||rolling)return;el.setPointerCapture(e.pointerId);drag={index,x:e.clientX,y:e.clientY,el,ghost:null,pointer:e.pointerId};}
